{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Custom interactive GUI tool for album loudness analysis and automation generation. Features dedicated Mastering Vertical Zoom (-24..-6 dB), selectable ITU-R BS.1770 metrics (LUFS-S, LUFS-M, RMS), a one-click [REGENERATE ENVELOPES] button, live progress display, peak markers, and a comprehensive dynamics report.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 REAPER script that checks Take Envelopes on selected items:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab If the envelope is inactive/idle (e.g., Take Volume at 0 dB or no points), hides the envelope.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab If Take Volume is at a flat level other than 0 dB and the item has only one take, the value is multiplied into the Item Volume, and the envelope is cleared and hidden.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab If the envelope contains automation (variable points, curves, or Automation Items), it remains untouched.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Optionally hides Pan, Pitch, and Mute envelopes if they are in their neutral state (no changes).\sa180\par}
}

